    "comment": "上90.26/下91.75<br>微積分98/90<br>普物84/92<br>工程數學一 92<br>電路學85<br>基本上微積分普物顧好就沒什麼問題，我自認微積分和普物不算太高，所以應該85分以上就行了。然後因為我是下學期在決定要轉光電的，我原系的課只退了系上的水文學，另外加簽光電的課。<br>蠻推薦先修光電的工數一和電路學，工數一主要在教線性代數，基本上都是高中的內容，考試都考作業勾題，教授給分也蠻甜的；電路學主要都考課本後面的練習題，如果真的考不太好，教授也會救人。<br>備取部分我就從修光電的課所以對光電感到有興趣做延伸，如果剛好沒衝堂，蠻建議先修光電的課程，對備審可能有加分？<br>最後祝學弟妹都能轉成功，轉光電應該比其他熱門系容易一些👍<br>",
