    "department": "社會科學院",
    "comment": "成績、選課：<br>上下學期都沒有到1/3的標準，下學期有點懈怠，成績退步不少，但有修過微積分可以讓標準降低很多，可以修的話儘量修，我自己有修經濟學原理一二（85/87），感覺能過這應該佔一部分，我覺得修過之後備審比較好寫一些，也可以確定自己是不是真的感興趣，建議經濟系的課可以先多修一點（當然成績不要太難看），然後適當退掉一些系上的課。<br><br>面試問題：<br>有被問到什麼契機讓你決定轉到經濟系（具體事件）、對於川普的關稅政策有什麼看法、為什麼修微積分、未來規劃、沒轉過會怎麼辦，還有被問到為什麼沒有打算雙主修等，我自己是覺得沒有被問太刁難的問題，基本上會針對書審資料問，真的就像聊天一樣，不要太緊張，另外穿著可以盡量正式一點。<br>祝各位轉系成功！",
