    "comment": "學期分數 90.7/91.5<br>GPA 4.18/4.21<br>微積分92/92<br>普物91/92<br>普化96/92<br>普物實驗92/95<br><br>我的系給分好像都沒有給很高 所以如果你也這樣的話 也別氣餒 也讓自己的排名在前幾名 還是都有機會的。當初我有想過因為給分不高 要不要把必修全部退掉 但我覺得這樣的風險太大(我們系只承認自己系開設的課) 那這樣乾脆不如重考 但後來有去電機系課表看一下 我就只把普化實驗退掉 (反正沒修 轉不過去也不影響大二大三大四課業 ) 我在大一下有修一門都計系的計算機概論(91分)。我基本是平日下課沒事就會到圖書館看書 五六日休息。把成績顧好 說不定還可以轉學之類的 就算都沒有 至少還有好看的成績。<br>加油!!!",
    "confirm": "true"
