    "comment": "分數難看沒關係可以放上自己做的project還有作品集，這大概是我能上的主要原因了，裡面涵蓋了在原系做的作品以及小遊戲。<br>建議程式相關作品可以放上Github然後在備審裡面貼上連結。<br>微積分與普物、程式設計請務必顧好，雖然分數也沒好看到哪裡就是了，我的分數是被其他的科目拉下來的，微積分91/88，普物92/87，供參。",
