    "comment": "大一修微積分 有過但成績很不好看<br>大二修經原 上下學期都81<br>大一有申請但沒轉過<br>我兩年的排名都不高 沒有到規定的前1/3<br>但有修微積分可以讓標準變成學期成績70就好<br>因為成績沒有很漂亮還是通過了<br>所以我猜應該是看動機大於分數跟排名<br>面試有問為什麼喜歡經濟/未來想往哪個方向/在原系有學到什麼以後可以利用的<br>以第一年失敗的經驗當參考我覺得是因為準備的時候就要展現出目標系的拉力 而不是原系的推力 可以寫在備審裡面&面試的時候跟教授分享<br>因為在準備的時候看大家的分享得到了很多幫助 所以也來分享自己的資訊 祝大家轉系成功",
