    "department": "電資學院",
    "comment": "兩學期排名都9.多%<br>總平均: 87/90<br>微積分: 99/99<br>普物: 72/76 超爛QQ<br><br>雙轉輔都申請，結果先通知雙輔沒通過，過了一個禮拜才公布轉系過了<br>沒有先修過資工系或程式相關的課，備審只有放自己練習的一些非常基礎的程式+轉系的動機，申請時最重要的應該還是成績<br>這年申請的表單上有特別要填111上學期平均和微積分一、二的成績，所以微積分要特別顧好<br>如果沒有先修過物理應該沒差，可以轉系後再修，但這樣之後應該很忙，建議先挑甜一點的來修",
