    "comment": "雙轉輔都有申請，生科系轉系沒有門檻就是交備審資料跟成績單，今年一個人都沒收，大一上學期有點混學期分數78.11下學期往前追學期分數89系排5，有修普生（一），普生（二）退選了，不知道是不是因為這個影響到了，但雙輔門檻是學期成績75以上，我89不知道為什麼沒過^^",
