    "comment": "資訊系自己的申請表單有要求填微積分(一)(二)的分數，所以我猜這可能也會影響結果。<br><br>我自己:<br>學期成績 88.6/85<br>微積分(一)(二) 100/100<br>程設(一) 7x <br>申請只交了成績單和成績證明出去<br><br>程設一是棄掉原系必修去資訊系修的，然後分數出來又超爛，所以我放棄丟資訊轉系QQ，連丟雙主都蠻挫。但如果原系大一沒程式相關的課，還是建議想辦法去外系(資訊、工科、工資...)修一門，除非是本來就有些project可以放備審啦!<br>反正重點就是要讓教授知道你寫得出一點東西<br>",
