    "comment": "1. 一定要在轉入物理系前就把「微積分」讀熟，後面的課程會大量使用。<br><br>2. 如果你在第二學期選課前就決定要轉物理系，那我強烈建議先修「物理數學(一)」。那是在第二學期物理系開給大一的必修課，之後課程也會用到。<br><br>3.「普通物理學」 當然分數越高越好，但不需要花太多時間。",
