    "comment": "門檻：考過建築系筆試、通過面試、學期成績平均>70<br><br>第一關是考畫圖的建築系筆試（性向測驗）<br>考題非常活，考創意和個人點子，每屆的題目都都不同，這次考的是給一篇文章以自己的視角畫出那座城鎮的樣貌，創造力成份非常高，平時可以多練習創作、速寫。<br><br>準備筆試的同時，可以一邊進行創作並累積成作品集，作品集少放素描或描繪靜物，也不建議畫室補習，教授們比較希望看到有特色的創作作品集，畫工反而不見得那麼重要。<br><br>作品集都是在面試的時候教授們先翻閱後問問題，也可能會以你作品集內容發問，要做好準備。面試教授會要求自我介紹，接著問想讀建築系的原因和對建築系的了解，還有問到在原系的經驗，還有說服他們錄取你。",
