    "comment": "本系的課都有修<br>但普物因為跟資訊的程設撞到 所以退掉<br><br>資訊相關的課有修資訊系程設一二<br>本系的計概+交管的計算機程式<br>分數都是96+<br><br>自己有資訊的專題5,6個<br>還有一些資訊活動的參與經歷<br>弄了一個網站來放<br>Github上也都有commit的紀錄<br><br>備審的話寫了5頁的樣子<br>簡單說一下經歷、成績還有專案的內容<br><br>雙主和轉都有投<br>但有過的只有轉<br>",
