    "in_maj": "工科系",
    "department": "工學院",
    "comment": "我在上學期主力其實是放在轉學考（微積分：85 普物：80 平均85.15）下學期發現機會不大，才開始全力拼在校成績轉系，雖然微積分期中考爆了所以也沒多好（微積分：88 普物：97 平均90.45）<br>建議學弟妹一開始就決定將自己的目標放在轉系的話，就要好好把握關鍵科目，果斷退掉一些不需要的課，加油！",
