    "department": "工學院",
    "comment": "只能說轉系很看運氣，如果遇到爛教授你的分數就會很低，所以如果你下定決心要轉系，就算是必修課遇到爛教授也盡量換，工科轉系感覺學年平均87就很穩了，今年還比去年多收2個人。而且每年每個熱門系招收的人都不太一樣，這2年我看資工越收越多，電機越收越少，材料去年收13個今年收23個，所以天時地利人和也很重要。想轉系之前也可以先打聽哪些課不錯先修，這樣之後排課表也比較輕鬆。",
    "confirm": "true"
