    "comment": "沒有修過任何一堂資訊系開的課，在大一下學期退了一堂原系的必修，其他全部都按照原系的課修的，國文英文和通識也都正常修。<br>備審沒有寫很多，只放了原系程式相關課程的期中專案還有轉系動機，自認備審寫得沒有很好，所以顧好成績感覺還是蠻重要的？<br>這一年準備轉系的過程中我也常常遇到問題或是感覺到迷惘，所以如果有問題想問的話歡迎聯繫我~<br>anl14693421@gmail.com<br>最後祝各位都能去到自己想去的地方！",
