    "department": "工學院",
    "comment": "微積分75/80<br>普物84/93<br>普化85/74<br>學期平均83.4/86<br><br>雙轉同時申請都有過<br>分數不是太好看但主科在系上排名都有前十（下學期可能有前五），還算有稍微顧成績。化工系有自己的轉系申請書還有google表單要填，在填微積分普物普化成績時我有一並將排名標上去，歷年轉入都蠻多的但今年好像很少感覺沒什麼競爭，總歸還是成績顧好應該都能過！<br><br>",
