    "comment": "上學期成績蠻爛的，下學期雖然努力挽救分數，但平均還是很不好看qq<br>沒有修過相關課程，感謝老師願意給我機會哈哈<br>有問題的話可以直接打電話詢問系辦，老師人都很好～<br>祝福大家都能成功",
