    "department": "社會科學院",
    "comment": "成績：91.88 / 89<br>修課：經濟系經原 會計 微積分（都修一整年）<br>審查資料：<br>https://desert-legend-f20.notion.site/b318e3140ac14c44899b3edbf8e52f6d<br>面試：<br>三個教授對一位學生 7min響一聲 8min結束<br>1. 備審相關問題<br>備審有放高中營隊的東西，那你的經濟學能力在大一有什麼進步？<br>和其他同學相比，為什麼你能修那麼多經濟系的課？<br>2. 其他問題<br>自我介紹<br>自我介紹引伸問題<br>暑假在做什麼？<br><br>祝轉系成功<br><br>",
