    "comment": "上學期可以去修修看經濟學原理（不過聽說非常難加簽到），沒修到的話也可以去找管院的經濟學來修，因為學分是互相承認的，聽說如果拿到高分，對轉系加很多分。<br>非常建議去修微積分，不僅可以測試你是否真的能夠應付系上學科，如果拿到學分也能將轉系門檻降低（從系上排名前1/3變成學年平均70分），對於要轉到管院或是雙主修輔系也都是有幫助的。<br>系上必修的話，可以參考學長姐的意見，若是那種花很多時間，分數又很不好看的「玄學」，就果斷棄/退選，像我下學期就退了兩門必修只剩11學分。",
