    "comment": "大一全部都照著原系的課修，也沒退選過。沒修過任何一堂資訊系開的課，也沒修過任何一堂跟程式有關的課(只有旁聽一堂python通識)。<br><br>不過我用了非常多篇幅去寫我的程式經歷，列出我學過哪些程式、精通哪些程式的某些應用，並列出一些小專案(附上部分程式碼)，盡量表現出自己對程式的熱情還有一些學習過程中的反思(為什麼適合資訊系呀、做這些專案的目的是什麼呀、...)。<br><br>資訊系不單單只看學期成績來審核，所以若確定自己想轉系，拼成績之餘，也要撥空碰一下程式(哪怕只是單純打一打基本語法，當然產出一點小專案更好)。<br><br>轉系的路上常常都是孤獨的，我中途也放棄過好幾次，所幸期末考教授開恩，讓我學期成績不要那麼難看。<br>提交申請前，我也有向曾經轉系的前輩問一些建議，真的幫助我很多，所以，明年想轉到資訊系的學弟妹，有問題也能到下面那個ig帳號問我呦～(雖然我還很菜)<br>miyukisama.fans.club",
