    "comment": "微積分：87/100<br>普通物理學：97<br>普通化學：81/87<br>學期成績：84.71/92.25<br>  以上重點科目建議觀念釐清後配合大量做題，我自己是把原文書後面的習題（有答案的）全部做完，然後每天在圖書館唸書到9點；或是有可以獲取考古題的管道，就可以應付大學的課業，平時可以安排休閒活動抒壓。<br>  通識的部分很好拉分，我會去dcard和課業分享平台看一下評論，做足功課，修課也比較安心。<br>  最後，我認為轉系是一個煎熬的過程，但只要熬過就可以實現心之所向，祝福學弟妹都能轉到心目中理想的學系！<br>",
