    "comment": "「是什麼原因，讓你想轉心理系呢？」<br>在寫申請理由書前，不妨先好好想過這個問題。<br><br>我在去年申請上雙主修心理系，唸了一年後才決定轉系。知道自己的成績不高，因此希望能夠清楚向教授們表達為什麼已經雙主修了，而我最後決定轉系。理由書的內容大概五百多字，主要分為「雙主修的初衷」、「雙主修的收穫」、「為什麼想轉系」。如果能夠提到是什麼契機讓自己開始對心理學領域產生好奇，又在這之中對哪些領域特別感興趣，實際接觸過後有哪些想法，希望未來能夠往哪個方向更進一步探索等等，想來可以讓教授更了解你，有更多評斷的依據。<br><br>祝福想要轉系的你，一切順利、轉系成功！",
