    "comment": "微積分：88/88<br>普物：93/93<br>普化：92/86<br>把三大主科顧好，盡量把主科衝到90up，自己轉系的時候選擇會多一些。<br>但也不要認為只要顧自己系上的課業就好，當初以為只要把主科顧好，就可以轉得過去，所以放掉系上專業必修，因此搞得上學期總平均不高，下學期聽朋友耳聞才意識到「總平均」的重要性，因此總平均和排名才高了一些。<br>化工系每年收的名額基本上不會超過10個，所以如果要以比較不抖的情況轉過去，儘量讓自己的總平均維持在85up，應該就可以轉過去了。",
