    "comment": "我兩學期平均分數不算是特別高到很穩的那種，<br>修過資訊系的程設二還有暑期密集課程，個人認為修資訊系實際課程拿高分可能比學期總分高更重要<br>我的被審資料除了要求的資料外就是放寫過的程式、圖片或github 連結，然後稍微針對每一個程式做一點心得分享自己學到什麼，我都儘量簡明扼要，太長我覺得可能會模糊焦點。<br>另外朋友也建議過我要把課程所學跟轉系動機有連結關係可能更有說服力，我也照著做ㄌ。<br>我的結論是，被審資料寫的有誠意一點，然後試著多修資訊系的基本必修課，即使最後平均沒有90也還是有機會成功哦哦！",
