    "in_maj": "電機系",
    "department": "電資學院",
    "comment": "微積分  95/88<br>普物    98/100<br>電機的課  87/95/99<br><br><br>修課的話沒甚麼訣竅，普物微積分顧好就對了，這兩科是之後三電一工的基礎(尤其是一下普物)，也是電機教授決定你轉的轉不成功<br><br>通識的部分我沒特別去顧，所以通常平均都會被拉低，你也可以像某些人一樣靠著狂修通識或甜課刷到100或99來拉高妳的平均，只是可能轉過去會很辛苦而已。<br><br>還有轉過去之前建議先學過程式(C 或verilog)，不然可能二年級作業會交不出來。<br><br>如果你很有把握能轉過去的話，可以先去修電機的課，但是有可能會死在裡面，作業有夠硬而且分數很不甜，班平均和中位數都只有6X。像我手殘按到甲班的計概，老師會把你當作程式天才來教，作業的難度大概成exponential成長，你會一直聽到同學抱怨要熬夜打code之類的，建議有兩個肝再來修。<br><br><br>活動的話你可以轉過後再跑，當時沒參加幾次系上辦的活動，感覺蠻愧疚的，但是如果你大一修兩邊的硬課恐怕也沒剩甚麼時間了(電神除外)，那邊的課就足以占據你一大半的時間了。<br>社交的話，我覺得學長姐都超級有用的，他們都很熱心會給妳很多寶貴的建議及資源，也可以先認識一些電機的同學，轉過去很快就能融入了。<br><br>然後引用一下之前看到不錯的留言:能轉到電機只是地獄的開始，要趕快想辦法在電機系生存下來。<br><br><br>最後呼籲學弟妹，轉系後切記要尊重原系及每個系，不要憑著轉後的優越感而到處戰來戰去，那種心態是非常噁心的，每個系都有別的系而無法取代的專業，沒有貴賤之分。<br><br>祝福學弟妹能夠順利轉到與興趣相符的系~<br><br><br>",
