    "comment": "我覺得要轉系成功的話<br>就是打從一開始就下定決心<br>並且認定自己就是一個刷分怪<br><br>踏溯台南這種無意義的課我也刷到99<br>通識認真挑選好的就刷爛的就退<br><br>但是我活動社交也沒少跑<br>系上營隊夜衝夜唱喝酒都有<br>下午沒課騎車到外縣市找女友<br>不像有些同學可能怕分數保持不住<br>放棄社交生活之類的<br><br>這邊我想提一個很重要的點<br>課絕對不要翹<br>課絕對不要翹<br>課絕對不要翹<br>因為我是一個很懶散的人<br>上課沒去沒聽到的內容<br>回宿舍我一定不會補<br><br>而且我自認上課認真的話<br>對複習有很大幫助也很輕鬆<br>所以上課是我覺得真的蠻省時間的<br><br>另外我修了三堂程式相關的課程<br>分別100、接近100、90過<br>因為今年資訊系有特別增加要求<br>需要放修過程式相關課程大綱<br><br>另外在放備審的時候我放了一些<br>我自認在教授面前沒什麼用的程式<br>但都是我在課程中學習的結晶<br>所以學弟妹們想放的話我覺得可以放<br>讓教授知道你付出的過程<br>但可能我分數算是不低<br>所以這部分變得沒什麼參考價值<br><br>最後我想跟想轉系的學弟妹說<br>不要管別人怎麼看<br>只要你下定決心要刷分並且堅定目標<br>絕對沒有刷不到的分數<br>也沒有達不到的目標<br><br>祝你們都到想去的地方<br><br>",
