    "comment": "上學期                     <br>普化85                    <br>普物94                    <br>微積分88                <br><br>下學期<br>普化84<br>普物88<br>微積分88<br><br>分數都不是很高，所以轉入化工不算很難，只要稍微唸一下書就可以了，而且其他必修我也沒有退掉，因為化工大一也還有其他必選修，所以建議還是不要退掉普物普化其中一科要不然之後會補學分補的很辛苦。",
