    "comment": "微積分 85/91<br>普物 94/100<br>其實我學期分數和排名並不高<br>我想只要班上前幾名沒有要轉電機，基本上學期分數和排名掉一些都還有機會，總之就是盡可能把微積分和普物分數拉高就對了！",
