    "comment": "轉電機還是看微積分普物跟總成績吧~\n微積分 83/94\n普物      93/94\n只要這兩科顧好排名前三基本沒問題，如果前面的不轉電機總排掉一點應該也還好，轉系申請的時候可以跟同系的互相問問看，至少原係的認識以後轉過了不會太邊緣，如果一開始就下定決心要轉也可以把不夠甜的科目棄掉，利用通識衝高總分，不過建議還是修點有用的計概吧，不然之後被擋修真的頗痛苦，另外提醒: 如果沒有普化背景大二來修材導會有點小壓力喔~\n希望大家都能轉到自己喜歡的科系~~",
    "confirm": "true"
