    "department": "電資學院",
    "comment": "轉入電機最重要的三個成績—學期成績，微積分和普物。首先是學期成績，如果覺得某些科目去了(考爆)，可以在期中的時候退選，大部分在原系修的必修課到後來都只能轉成通識或是系外選修(降值)，不需要太執著過(也可以直接不修)。\n另外微積分跟普物成績很重要，兩個學期都能90以上就很穩了(前提是總成績不要太爛)。\n通識找甜的課(ex西方古典音樂、音樂舞島戲劇...)，沒意外都可以95以上，很好拉分。\n只要有心其實真的蠻好過的喔，不要太有壓力~希望這樣有幫助到下一屆的學弟妹。",
    "confirm": "true"
