    "department": "理學院",
    "comment": "我自己是本來就想轉化學所以有把系上的單學期普通化學、物理退掉改修外系（非化學系）的普通化學、物理（一）、（二），下學期還有修那該死的化學數學，這樣才能跟上同年級生的修課進度。\n\n但聽說化學系轉入不難，系辦自己都說他們轉系看很鬆。我想有心要轉的不要太擺爛都會過。",
