    "department": "管理學院",
    "comment": "-備審：除了自傳之外，我也有附上一個表格，說明大一所參加的所有課外活動（包含打工、社團、競賽等等）；而讀書計畫的部分則可以附上你所預計的學分表，說明你對轉系之後的課程是有規劃與安排的。\n-原系會轉到新系的困難：在原系的會計學（一）（二）的期中期末考，都以選擇或填充題居多。參考會計系朋朋的經驗之後發現會計系是考編表居多，可能在原系修習的課程不是那麼的扎實及有深度，需要靠日後重新修初級會計學（一）（二），或是自己念原文書將不太熟悉的地方補齊。",
