    "in_maj": "法律系",
    "department": "社會科學院",
    "comment": "成績要漂亮不是很認真讀書有用的，成績亮眼的關鍵，大概是三分靠讀書七分靠選課，選了一個硬課，就要選兩個甜課拉它，硬課要選讀書有用，分數不玄幻的課；甜課要讓老師認識你，有加分要加爆，有考試要好好考，記得坐第一排舉手問問題，最後開心拿98分大家好聚好散。\n\n轉法律系的話，真的就只是看成績，我大一修了一堆法律系的課，系上的課也沒退把自己弄爆後，成績大概系上排名十幾名，然後沒上。後來大二開始刷分數後才轉過去，可是大二還是有持續修法律系的必修和選修，主要是把政治系的必修退掉。\n\n雖然說是看成績，可是還是很推薦大家先修法律系的課，修看看才知道法律適不適合你，只是切記，有捨才有得，除非你有天賦異稟，不然本系課真的要考慮退，尤其是那種再怎麼努力，分數還是不會高的課。還有，通識記得選滿三科，最後全部刷到98分，用來拉你的必修，必修也最好選能80分以上的。\n\n能不能轉系，選課決定七成以上，切記切記。",
