    "comment": "統計系最大的門檻就是微積分和學期平均，微積分成有顧好學期成績大概就也不成問題～我的微積分上下學期平均大概92左右\n然後備審真的要認真做！我身邊也有朋友分數很高結果沒有過的！\n我在備審中有提到我修過統計相關課程，以及我從中產生的興趣和喜好等等；讀書計畫方面也可以提到對於未來想走的方向（想往統計的哪方面發展）\n\n希望想轉系的人都能成功～",
