    "comment": "資工系轉系呈交的資料只有成績單和備審兩個\n所以想拼資工轉系的人\n盡量要把總成績弄高\n或者是在備審中放入你為了轉資工系\n做了什麼準備（ex:程式作品或競賽）\n\n如果兩樣都能做到就穩了！\n\n如果能力有限\n可以先修資工系的課\n這樣除了成績單有修課紀錄\n說不定還會有程式作品放備審\n轉過去也減少學分壓力\n\n結論：總成績+程式作品",
