    "department": "社會科學院",
    "comment": "1.修課門檻必須達到<br>轉系申請條件中，該修的科目都必須要修(除非申請免修)，這點選課時就已經要開始注意了。<br><br>2.選課選甜<br>個人因為怕失敗，所以原系必修課全部有修，但只要是選修都退掉(聽說有硬課也可以退掉)。<br>通識課查好評價多修幾門，一方面拉高成績，一方面轉系成功以後必修課可能大塞車(大二大三課全部一起上)，沒時間or很少時間修。<br>但也不用太多，因為若轉成功，原系的課可以抵免為通識課，但要注意所屬領域學群問題。(ex個人原系中文系的必修，轉通識課後屬於人文學領域)<br>通識課個人偏好可以自己準備考試的課程，因為分組報告有可能遇到雷隊友。這方面可以自己斟酌。<br><br>3.成績要顧<br>大一時上課全勤，沒到必須要請假，寧願去課堂上睡著也不要缺席。<br>作業、考試必須努力準備，選到甜課涼課這時候就很重要。<br><br>4.諮詢學長姐<br>可以諮詢轉系成功過來人的經驗。",
