    "comment": "個人覺得不分系要求的是個人經歷\n而非分數上的呈現\n且經歷是與自身性向發展有關\n不單純只是參與校內大型活動的活動咖\n在大一的時候就自己找了校外實習的缺額\n然後從四月一直持續下去\n此外也長期參加校外鯨豚研究中心的志工\n不斷的找不同的領域嘗試\n不分系的老師很喜歡主動的學生\n平均85分在系上排名也只落在20名左右\n所以轉入不分系\n成績不是絕對\n而是看自己對於未來的積極度",
