    "in_maj": "資訊系",
    "department": "電資學院",
    "comment": "其實我那時候什麼資訊相關的課都沒修，就是照著自己本系的課程走。\n剛好當時同時正在準備重考，所以下學期的普化發現有點 ... 難維持就退掉了哈哈哈哈\n我覺得比較重要的應該是成績要顧好啦~\n問過幾個同屆的之後發現，可以問問同年級的有沒有人要轉，如果前面幾名都沒有要跟你搶名額的話應該比較容易轉成功的感覺。像我們這屆同系的似乎是卷1跟卷3(我)都轉資訊，後面的人就被刷掉的樣子。但是別系的同學學期成績跟排名都普通，但前幾名都沒有轉資訊他就成功了。",
