    "comment": "其實我認識的轉資訊系成功的人裡面滿多人之前沒有甚麼特別的程式背景，所以努力拚好成績最重要(目前問到這年轉進來的人裡面最低平均大概是84，可以參考一下)。<br><br> 因為以前有些程式基礎，我大一下的時候把會計退掉去修資訊系的程設二(直接跳過程設一)，在交申請動機的時候也附上了這堂課的專案的Github repo(可以想像成是方便管理程式碼的雲端硬碟)。另外因為要衝平均，下學期我也把運輸學退掉了。<br><br>交管系理論上大二以前如果不退課，完全沒辦法修到資訊系的基礎課程，所以如果要雙主或輔系的要考量一下，很有可能會延畢。但如果是交管轉資訊的話，交管大一計概、微積分上下都能抵免(資訊系抵免的標準還滿寬鬆的，就算不在等同課程內，只要名字一樣都能試試看)。<br><br>進來之後因為商用微積分和工程微積分不一樣，大二上讀工數的時候會比較辛苦，但如果撐的過去，基礎課程大三甚至大二結束的時候就能全部補完，理論上可以準時畢業。<br><br>準備轉系是一趟煎熬、辛苦的旅程，但不管中間發生了什麼事情，能決定能不能轉系成功的，只有你自己。",
